// Writes 20-vanilla-combinations.feature: the sixteen outfits Virginie chose on 2026-10-15 for the
// 1.0.0 vanilla scope (vanilla garments, Underwhere's underwear, Vanilla Apparel Expanded), on the
// ten WDI profiles, one scenario per facing, one capture per outfit.
// Generated feature: do not edit it by hand. Pass: wsl-deps.vanilla-combinations.map.
const fs = require('fs');

const people = [
  ['M-Thin', 'male', 'Thin', 196, 186, false], ['M-Avg', 'male', 'Male', 198, 186, false],
  ['M-Fat', 'male', 'Fat', 200, 186, false], ['M-Hulk', 'male', 'Hulk', 202, 186, false],
  ['M-Kid', 'male', 'Child', 204, 186, true], ['F-Thin', 'female', 'Thin', 196, 184, false],
  ['F-Avg', 'female', 'Female', 198, 184, false], ['F-Fat', 'female', 'Fat', 200, 184, false],
  ['F-Hulk', 'female', 'Hulk', 202, 184, false], ['F-Kid', 'female', 'Child', 204, 184, true]
];
const kid = p => p[5], female = p => p[1] === 'female';
// Underwear by profile: children the loincloth, men the boxers, women the panties.
const under = p => kid(p) ? 'UnderWhere_Loincloth' : female(p) ? 'UnderWhere_Panties' : 'UnderWhere_Boxers';
const bra = p => female(p) && !kid(p) ? ['UnderWhere_Bra'] : [];
// A child wears the kid version where vanilla has one.
const kidOf = { Apparel_BasicShirt: 'Apparel_KidShirt', Apparel_Pants: 'Apparel_KidPants', Apparel_TribalA: 'Apparel_KidTribal' };
const fit = (p, items) => items.map(i => kid(p) && kidOf[i] ? kidOf[i] : i);

const outfits = [
  ['T-shirt and boxers', p => [kid(p) ? under(p) : 'UnderWhere_Boxers', ...fit(p, ['Apparel_BasicShirt'])]],
  ['T-shirt and panties', p => [kid(p) ? under(p) : 'UnderWhere_Panties', ...fit(p, ['Apparel_BasicShirt'])]],
  ['bra and pants', p => [under(p), ...bra(p), ...fit(p, ['Apparel_Pants'])]],
  ['bra and shorts', p => [under(p), ...bra(p), 'VAE_Apparel_Shorts']],
  ['bra and skirt', p => [under(p), ...bra(p), 'VAE_Apparel_Skirt']],
  ['tribalwear', p => [under(p), ...fit(p, ['Apparel_TribalA'])]],
  ['formal vest over T-shirt and pants', p => [under(p), ...fit(p, ['Apparel_BasicShirt', 'Apparel_Pants']), 'Apparel_VestRoyal']],
  ['jeans and button-down shirt', p => [under(p), 'Apparel_CollarShirt', 'VAE_Apparel_Jeans']],
  ['tank top and shorts', p => [under(p), 'VAE_Apparel_TankTop', 'VAE_Apparel_Shorts']],
  ['hoodie and trousers', p => [under(p), 'VAE_Apparel_Hoodie', 'VAE_Apparel_Trousers']],
  ['overalls over T-shirt', p => [under(p), ...fit(p, ['Apparel_BasicShirt']), 'VAE_Apparel_Overalls']],
  ['tribal kilt and chestwrap', p => [under(p), 'UnderWhere_Chestwrap', 'VAE_Apparel_TribalKilt']],
  ['long johns', p => ['UnderWhere_LongJohns']],
  ['jacket over T-shirt and pants', p => [under(p), ...fit(p, ['Apparel_BasicShirt', 'Apparel_Pants']), 'Apparel_Jacket']],
  ['duster over T-shirt and pants', p => [under(p), ...fit(p, ['Apparel_BasicShirt', 'Apparel_Pants']), 'Apparel_Duster']],
  ['T-shirt and pants', p => [under(p), ...fit(p, ['Apparel_BasicShirt', 'Apparel_Pants'])]]
];
const requires = '@requires:wdi.realistic.bodies @requires:Malistaticy.UnderWhere @requires:VanillaExpanded.VAPPE @requires:nalsnoir.ApparelPaperPattern @requires:ab.vplrf @requires:LoneKin.ChildrenWearAnything @requires:nelim.pickletools.screenshotstudio @requires:nelim.pickletools.colonistrace';
const out = [
  '# The sixteen outfits of the 1.0.0 vanilla scope (Virginie, 2026-10-15) on the ten WDI profiles, one',
  '# scenario per facing. Vanilla garments, Underwhere\'s underwear, Vanilla Apparel Expanded; no UNAGI, no LEWD.',
  '# Generated by gen-vanilla-combinations.js; do not edit by hand. Pass: wsl-deps.vanilla-combinations.map.',
  '@review @vanilla-combinations @timeout:900', 'Feature: the 1.0.0 outfits on every WDI silhouette, three facings', '',
  '  Background:', '    Given the save "Nelims-tribe" is loaded', '    And game speed is paused', ''
];
const line = (s = '') => out.push(`    ${s}`);
for (const facing of ['South', 'East', 'North']) {
  out.push(`  ${requires}`);
  out.push(`  Scenario: the 1.0.0 outfits on ten WDI silhouettes, facing ${facing}`);
  line('Given Nelim\'s Sanctuary: the animals are removed from the sanctuary "calm-zone-close"');
  line('And Nelim\'s Pickle Tools: the other colonists are out of frame');
  for (const p of people) {
    line(`And a colonist "${p[0]}" exists`);
    if (kid(p)) line(`And "${p[0]}" is 8 years old`);
    line(`And "${p[0]}" gender is ${p[1]}`);
    line(`And Nelim's Pickle Tools: "${p[0]}" body type is ${p[2]}`);
    line(`And Nelim's Pickle Tools: "${p[0]}" stands at (${p[3]}, ${p[4]}) facing ${facing}`);
    line(`And I draft "${p[0]}"`);
  }
  for (const [label, clothes] of outfits) {
    for (const p of people) {
      line(`And I destroy the gear of "${p[0]}"`);
      for (const item of clothes(p)) line(`And Nelim's Pickle Tools: "${p[0]}" wears "${item}"`);
    }
    line('And Nelim\'s Sanctuary: I am at the sanctuary "calm-zone-close"');
    line('And Nelim\'s Pickle Tools: studio presentation mode is enabled');
    line('And I wait 120 ticks');
    line(`And I take a screenshot "vanilla combinations, ${facing}, ${label}"`);
  }
  line('Then no warning matching "Failed to find any textures" was logged');
  out.push('');
}
fs.writeFileSync(__dirname + '/20-vanilla-combinations.feature', out.join('\n'));
console.log('wrote 20-vanilla-combinations.feature');
